const __pageData = JSON.parse('{"title":"12. ROS + OpenCV Lesson","description":"","frontmatter":{},"headers":[],"relativePath":"docs/12.ROS + OpenCV Lesson.md","filePath":"docs/12.ROS + OpenCV Lesson.md"}');
